package com.ruoyi.web.controller.projectmanagement;
import com.ruoyi.common.core.controller.BaseController;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.common.core.page.TableDataInfo;import com.ruoyi.projectmanagement.execution.domain.LifecycleActionRequest;import com.ruoyi.projectmanagement.task.domain.ProjectTask;import com.ruoyi.projectmanagement.task.service.IProjectTaskService;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/projectManagement/task") public class ProjectTaskController extends BaseController {private final IProjectTaskService service;public ProjectTaskController(IProjectTaskService s){service=s;}@GetMapping("/list")public TableDataInfo list(ProjectTask f){startPage();return getDataTable(service.list(f));}@GetMapping("/{id}")public AjaxResult get(@PathVariable Long id){return success(service.get(id));}@PostMapping public AjaxResult add(@Validated @RequestBody ProjectTask t){int rows=service.add(t,getUsername());AjaxResult r=toAjax(rows);if(rows>0)r.put("data",t.getTaskId());return r;}@PutMapping public AjaxResult edit(@Validated @RequestBody ProjectTask t){return toAjax(service.edit(t,getUsername()));}@DeleteMapping("/{id}")public AjaxResult remove(@PathVariable Long id){return toAjax(service.remove(id,getUsername()));}@PostMapping("/{id}/lifecycle")public AjaxResult lifecycle(@PathVariable Long id,@Validated @RequestBody LifecycleActionRequest r){return toAjax(service.lifecycle(id,r,getUsername()));}}
